class Person:
    def __init__(self, name):
        self.name = name

class Student(Person):
    def __init__(self, name, roll):
        super().__init__(name)
        self.roll = roll

class Teacher(Person):
    def __init__(self, name, subject):
        super().__init__(name)
        self.subject = subject

s = Student('Ravi', 23)
t = Teacher('Meera', 'Python')
print(s.name)
print(s.roll)
print(t.name)
print(t.subject)
